export const MENU_PHOTOS={toho:{file:'yagan.webp',flip:false},yamanote:{file:'yamanote.webp',flip:true},chuo:{file:'chuo.webp',flip:true},osaka:{file:'osaka.webp',flip:true},tokaido:{file:'tokaido.webp',flip:false},tohoku:{file:'tohoku.webp',flip:true},yagan:{file:'yagan.webp',flip:true}};
export function setMenuPhoto(routeId){const photo=MENU_PHOTOS[routeId]??MENU_PHOTOS.yamanote;for(const img of document.querySelectorAll('.menu-route-photo')){const src=new URL('./assets/menu-photos/'+photo.file,import.meta.url).href;if(img.src!==src)img.src=src;img.classList.toggle('photo-flipped',photo.flip);}}
export function mountMenuMusic(getVolume,{active=true}={}){const audio=new Audio(new URL('./assets/mainmenu.mp3',import.meta.url));audio.loop=true;audio.preload='auto';let menu=active,unlocked=false;function sync(){audio.volume=getVolume();if(menu&&!document.hidden){if(audio.paused)audio.play().catch(()=>{});}else audio.pause();}function unlock(){unlocked=true;sync();}document.addEventListener('pointerdown',unlock);document.addEventListener('keydown',unlock);document.addEventListener('visibilitychange',sync);addEventListener('pagehide',()=>audio.pause());sync();return {setMenu(value){const entering=Boolean(value)&&!menu;menu=Boolean(value);if(entering)audio.currentTime=0;sync();},setVolume(){audio.volume=getVolume();},audio};}
